mapper.insert:
insert into idempotency_record(
    idempotency_key, actor, request_hash, status, response_status, response_json,
    created_at, expires_at, lease_expires_at, owner_token
) values (
    #{idempotencyKey}, #{actor}, #{requestHash}, #{status}, 0, '',
    #{createdAt}, #{expiresAt}, #{leaseExpiresAt}, #{ownerToken}
)

mapper.delete:
delete from idempotency_record
 where idempotency_key = #{idempotencyKey}
   and status = 'IN_PROGRESS'
   and owner_token = #{ownerToken}

mapper.update:
update idempotency_record
   set lease_expires_at = #{leaseExpiresAt}
 where idempotency_key = #{idempotencyKey}
   and status = 'IN_PROGRESS'
   and owner_token = #{ownerToken}

update idempotency_record
   set lease_expires_at = #{leaseExpiresAt},
       owner_token = #{newOwnerToken}
 where idempotency_key = #{idempotencyKey}
   and status = 'IN_PROGRESS'
   and actor = #{actor}
   and request_hash = #{requestHash}
   and lease_expires_at is not null
   and lease_expires_at < #{now}

mapper.delete:
delete from idempotency_record
 where idempotency_key = #{idempotencyKey}
   and expires_at <= #{now}
